+type CreatePayloadClientParams = {
+  fetchFn?: typeof fetch;
+  baseUrl?: string;
+  token?: string;
+};
+
+export const createPayloadClient = ({ fetchFn = fetch, baseUrl, token }: CreatePayloadClientParams = {}) => {
+  const headers = new Headers();
