+  return new PayloadSDK({
+    baseURL: baseUrl,
+    fetch: async (url, init?) => {
+      const response = await fetchFn(url, {
+        ...init,
+        headers: new Headers({ ...headers, ...init?.headers }),
+        credentials: 'include',
